  'klejkaja-lenta': {
    images: [
      'https://invit.by/image/data/krovlya/lenta_klej.jpg',
    ],
    blocks: [
      { kind: 'heading', text: 'Описание' },
      { kind: 'text', text: 'Клеепереносящая (трансферная) лента на основе синтетического каучукового клея, армированная полиэфирным сетчатым волокном. По сути такая лента представляет собой тонкий слой адгезива на армирующей сетке, нанесенный на специальную, легко отделяемую подложку (антиадгезионный материал). Тонкое сетчатое волокно (армирование) придаёт ленте пространственную стабильность и не даёт просачиваться внутрь материала, что особенно важно для склеивания пористых материалов.' },
      { kind: 'text', text: 'Лента специально разработана для применения на пористых и неровных поверхностях, где требуется высокая начальная адгезия, в том числе к сложным поверхностям (ПС, ПП, ПЭ, ППУ, каучук и др.) и устойчивость к влаге. Специальный адгезив разработан для применения при низких эксплуатационных температурах и позволяет проводить монтаж вплоть до -25°С.' },
      { kind: 'text', text: 'Основное применение – ламинация изделий из пенополиуретана (поролона), вспененного полиэтилена и полистирола к металлическим, деревянным поверхностям, бетону и поверхностям, обработанным битумом, производство строительных изоляционных материалов и плёнок, крепление бумаги, пластиков, плёнок и любых других лёгких материалов.' },
      { kind: 'heading', text: 'Строение' },
      { kind: 'list', items: ['Лайнер: силиконизированная бумага-глассин (цвет горчичный), вес 82 г/м.кв', 'Клей: синтетическая смола, цвет желтоватый, армированный сетчатым полиэфирным волокном.'] },
      { kind: 'heading', text: 'Технические характеристики' },
      { kind: 'list', items: ['Толщина без учёта лайнера: 80±4 мкм (с сеткой),', 'Нанос клея: масса слоя клея не менее 75±5 г/м.кв,', 'Усилие отслаивания* (адгезия): не менее 22 Н/25 мм,', 'Температурный режим применения: от -20°C до +60°C,', 'Эксплуатационный диапазон температур: от -40°C до +70°C,', 'Ширина клеевой полосы, мм: 8 - 1000,', 'Намотка в рулоне, мп: 50, 100, 200, 500.'] },
      { kind: 'heading', text: 'Область применения' },
      { kind: 'text', text: 'Клеепереносящую ленту применяют при монтажных работах различной сложности: монтаж деталей автомобилей и другой техники, уплотнительных материалов (прокладок), нетканых материалов и изоляционных пленок, для изготовления самоклеящихся декоративных панелей, склеивания двух поверхностей между собой, а также позволяет усовершенствовать и упростить процесс производства мебели, одежды, промышленных товаров, строительных деталей. Главным достоинством клеепереносящей ленты является возможность изготовления самоклеящихся материалов на любой основе, в том числе и сложной формы, без использования дорогостоящего оборудования и больших затрат.' },
    ]
  },
