  'germetik-poliuretanovyj-pu40-starfix-seryj-belyj': {
    images: [
      'https://invit.by/image/data/germetiki/germetik_poliuretanovyj_PU40_belyj.png',
    ],
    blocks: [
      { kind: 'heading', text: 'Описание продукта' },
      { kind: 'text', text: 'Однокомпонентный высокомодульный герметик на основе полиуретана. Полимеризуется под действием влаги окружающего атмосферного воздуха. Обладает отличной адгезией ко многим материалам: цементу, кирпичу, керамике, полиуретану, эпоксидной смоле, большинству полиэфиров, большинству металлов и древесины. Используется для склеивания или герметизации швов между большинством строительных материалов где требуется высокая или средняя прочность соединения. Используется для уплотнения швов/герметизации трубных каналов/вентиляционных систем. Имеет множество применений в металлических и деревянных конструкциях. Не применяется с полиэтиленом, полипропиленом и тефлоном.' },
      { kind: 'heading', text: 'Способ применения полиуретанового клея-герметика PU40 STARFIX' },
      { kind: 'text', text: '1. Очистите и высушите поверхность.' },
      { kind: 'text', text: '2. Проткните наконечник алюминиевой трубки кончиком пластиковой насадки-аппликатора.' },
      { kind: 'text', text: '3. Обрежьте насадку-аппликатор под углом 45° до нужного размера и накрутите эту насадку-аппликатор на картридж.' },
      { kind: 'text', text: '4. Снимите нижнюю часть картриджа (защитный колпачок).' },
      { kind: 'text', text: '5. Установите картридж в пистолет-аппликатор и держите его под углом 45°. Нанесите сплошной и ровный слой с одной стороны, не допуская образования отверстий или пузырей.' },
      { kind: 'text', text: '6. Удалите излишки продукта. После вскрытия используйте все содержимое.' },
      { kind: 'text', text: '7. Не наносить на открытом воздухе, если в течение 2 часов после нанесения возможен дождь.' },
      { kind: 'heading', text: 'Условия применения' },
      { kind: 'text', text: 'ТЕМПЕРАТУРА ПРИМЕНЕНИЯ: от +5 до +45.' },
      { kind: 'text', text: 'Время высыхания: Образует пленку в течение 1-2 часов и отверждевает на 3 мм каждые 24 часа при температуре 23°C' },
      { kind: 'text', text: 'Условия хранения: 12 месяцев в оригинальной невскрытой упаковке в сухом и прохладном месте при температуре от +5 до 27, влажности от 30% до 70%. Оптимальным является хранение в нижней половине указанного диапазона температур и влажности. Во избежание загрязнения неиспользованного продукта не возвращайте материал в оригинальную упаковку.' },
    ]
  },
