  'smazochno-ochistitel%27naja-smes%27-wd-40': {
    images: [
      'https://invit.by/image/data/germetiki/smazochno_ochistitel%27naja_smes%27_WD_40_300_ml.png',
    ],
    blocks: [
      { kind: 'heading', text: 'Описание товара' },
      { kind: 'text', text: 'Смазочно-очистительная смесь WD-40 вытесняет влагу и образует защитный барьер против сырости, защищает от коррозии даже в самых экстремальных условиях, смазывает детали, не оставляя жирных или липких следов, проникает в механизмы, освобождая заржавевшие части; легко удаляет жир, битумные пятна или остатки клея.' },
      { kind: 'text', text: 'WD-40 можно наносить практически на все. Это средство безопасно для металла, резины, дерева, пластика. WD-40 можно наносить на окрашенные металлические поверхности безо всякого вреда для краски. Однако для некоторых поверхностей, например поликарбонатов и чистого полистистирола, следует избегать обработки продуктами, полученными из нефтяного сырья, такими как WD-40.' },
      { kind: 'heading', text: 'Пять основных функций смазки WD-40' },
      { kind: 'list', items: ['Очищает: WD-40 проникает под грязь, сажу и смазочные вещества, чтобы очистить поверхность. Также WD-40 растворяет клейкие вещества, позволяя легко удалять этикетки, клейкую ленту и излишнее количество клея.', 'Замещает влагу: WD-40 может вытеснять влагу, что позволяет устранять проводимость, вызванную сыростью в электронных системах.', 'Проникает: WD-40 ослабляет сцепление между металлом и ржавчиной, позволяет устранить прикипание и сцепление смерзшихся металлических частей.', 'Смазывает: смазывающие ингредиенты WD-40 широко рассеиваются и прочно удерживаются на движущихся частях.', 'Защищает: WD-40 защищает металлические поверхности ингредиентами, обеспечивающими сопротивление коррозии, которые предохраняют металл от влаги и других причин коррозии.'] },
    ]
  },
