  'dempfernaja-lenta-dlja-stjazhki-pola': {
    images: [
      'https://invit.by/image/data/PES/dempfernaja_lenta.jpg',
    ],
    blocks: [
      { kind: 'heading', text: 'Описание продукта' },
      { kind: 'text', text: 'Демпферная лента ПЭС Евробанд производится из физически сшитого пенополиэтилена ППЭ. Демпферная лента Евробанд имеет одну клейкую сторону, клеевой слой защищен антиадгезионной пленкой, поверхность материала гладкая, структура закрытопористая. Такая лента выполняет роль теплового шва при устройстве теплых водяных полов. Часто ленту используют в качестве уплотнителя стыков, а также для герметизации зазоров и щелей. Демпферная лента Евробанд ПЭС из ППЭ обеспечивает теплоизоляцию пола, уменьшает теплопотери через боковые стены здания. Лента ПЭС EUROBAND из физически сшитого пенополиэтилена ППЭ - это долговечный материал с превосходными термо-, звуко- и влагоизоляционными свойствами. Лента имеет низкий коэффициент теплопроводности и высокий коэффициент звукопоглощения, высокую стойкость к воздействию прямых солнечных лучей, влаги, высоких и низких температур.' },
    ]
  },
