  'paroizoljacionnaja-lenta-euroband-vla': {
    images: [
      'https://invit.by/image/data/GIL%20PIL/lenta_euroband_%20vla.jpg',
    ],
    blocks: [
      { kind: 'heading', text: 'Описание продукта' },
      { kind: 'text', text: 'EUROBAND ВЛ(а) – это пароизоляционная лента, предназначенная для герметизации примыканий оконного (дверного) блока к стеновому проему внутри помещения. Благодаря своим свойствам влаго- и паронепроницаемости внутренняя оконная лента EUROBAND ВЛ(а) идеально подходит для изоляции внутреннего слоя монтажного шва и может монтироваться практически на все типы монтажных поверхностей.' },
      { kind: 'text', text: 'Пароизоляционная внутренняя лента EUROBAND ВЛ(а) производится на основе металлизированной пленки, дублированной высокопрочным нетканым полотном. Нетканое полотно обеспечивает оптимальное сцепление со штукатурными, шпаклевочными растворами и клеем. На ленте имеются две клейкие монтажные полосы с одной (под заказ) или с двух разных сторон. Одна полоса выполнена из акрилового клея, армированного сеткой, другая – из высококачественного бутилкаучука высокой степени клейкости.' },
      { kind: 'heading', text: 'Преимущества пароизоляционной ленты EUROBAND ВЛ(а)' },
      { kind: 'list', items: ['Высокая пароизоляция, гидроизоляция и ветрозащита,', 'Высокое адгезионное сцепление монтажно-герметизирующих полос,', 'Возможность окрашивания и нанесения штукатурного раствора (мокрый способ отделки),', 'Возможность отделки монтажного шва сухим способом (пластиковые откосы, сэндвич-панели и др.),', 'Препятствует выпадению конденсата на поверхности внутренних откосов,', 'Возможность монтажа на любые типы поверхностей,', 'Экономичность и безотходность материала,', 'Долговечность при эксплуатации.'] },
      { kind: 'heading', text: 'Размерный ряд' },
      { kind: 'text', text: 'Лента ВЛ(а) выпускается в рулонах 5-ти типоразмеров по ширине.' },
      { kind: 'table', headers: ['Ширина ленты ВЛ(а), мм', 'Количество в рулоне, мп', 'Количество в коробке, мп'], rows: [
        ['70', '25', '175'],
        ['80', '25', '150'],
        ['100', '25', '125'],
        ['120', '25', '100'],
        ['150', '25', '75'],
      ] },
      { kind: 'text', text: 'Под заказ изготовим ленты других размеров' },
      { kind: 'heading', text: 'Рекомендации по монтажу ленты EUROBAND ВЛ(а)' },
      { kind: 'text', text: 'Лента EUROBAND ВЛ(а) – это готовый к применению продукт. При установке ленты EUROBAND ВЛ(а) не требуется специальных инструментов. Перед монтажом ленты необходимо очистить поверхность оконного проема от строительного мусора, пыли или наледи. При необходимости следует обработать поверхность стен грунтовочным составом. Приклеивать ленту необходимо плотно по всей ее длине. Стыковка отрезков ленты производится внахлест. Рекомендуется приклеивать ленту до полного расширения монтажной пены. Это нужно для того, чтобы монтажная пена при расширении приклеила к себе ленту и немного ее натянула для более удобной работы при последующем оштукатуривании откосов. Длина ленты, необходимая для монтажа в конкретном случае, складывается из габаритного размера оконного блока с добавлением отрезка ленты, равному ее ширине. Прибавление отрезка ленты в размер её ширины требуется для перехлеста соединяемых частей ленты. Это позволит создать надежную пароизоляцию стыка по всему периметру окна. Затем с ленты удаляется антиадгезионная прокладка, защищающая клейкую монтажную полосу, и она крепится к коробке оконного блока. Далее подготовленный оконный блок вместе с приклеенной лентой помещается в проем, выставляется по уровню и отвесу и крепится крепежными элементами к стене. На следующем этапе монтажный зазор заполняется монтажной пеной. Со второй монтажно-герметизирующей полосы ленты снимается антиадгезионная прокладка, и лента приклеивается к откосу. При этом концы вертикальных отрезков ленты загибают на горизонтальные откосы, а концы горизонтальных отрезков – на вертикальные откосы.' },
      { kind: 'heading', text: 'Файл для скачивания:' },
      { kind: 'text', text: 'Технический лист пароизоляционная лента EUROBAND ВЛ(а)' },
    ]
  },
