  'diffuzionnaja-lenta-euroband-nl': {
    images: [
      'https://invit.by/image/data/GIL%20PIL/lenta_euroband_nl.jpg',
    ],
    blocks: [
      { kind: 'heading', text: 'Описание продукта' },
      { kind: 'text', text: 'EUROBAND НЛ – это гидроизоляционная паропроницаемая (диффузионная) лента, предназначенная для водоизоляции монтажного шва светопрозрачной конструкции со стороны улицы, в том числе под отливом. Благодаря своим свойствам наружная оконная лента EUROBAND НЛ защищает монтажный шов с внешней стороны от проникновения влаги и воды при давлении до 1000 Па и одновременно обеспечивает диффузию водяного пара. Таким образом, герметизируемый шов остается вентилируемым.' },
      { kind: 'text', text: 'Наружная диффузионная водоизоляционная лента EUROBAND НЛ производится на основе прочной полипропиленовой пленки, дублированной нетканым материалом с двух сторон. Это «дышащий» материал мембранного типа. На ленте имеются две клейкие монтажные полосы с одной или с двух разных (под заказ) сторон. Одна полоса выполнена из акрилового клея, армированного сеткой, другая – из высококачественного бутила серого цвета, обладающего очень хорошей адгезией.' },
      { kind: 'heading', text: 'Преимущества паропроницаемой ленты EUROBAND НЛ' },
      { kind: 'list', items: ['Высокая гидроизоляция,', 'Высокая степень паропроницаемости,', 'Высокое адгезионное сцепление монтажно-герметизирующих полос,', 'Возможность монтажа на любые типы поверхностей,', 'Высокая скорость монтажа,', 'Долговечность при эксплуатации,', 'Экономичность и безотходность материала.'] },
      { kind: 'heading', text: 'Размерный ряд' },
      { kind: 'text', text: 'Лента НЛ выпускается в рулонах 5-ти типоразмеров по ширине.' },
      { kind: 'table', headers: ['Ширина ленты НЛ, мм', 'Количество в рулоне, мп', 'Количество в коробке, мп'], rows: [
        ['70', '25', '175'],
        ['80', '25', '150'],
        ['100', '25', '125'],
        ['120', '25', '100'],
        ['150', '25', '75'],
      ] },
      { kind: 'text', text: 'Под заказ изготовим ленты других размеров' },
      { kind: 'heading', text: 'Применение' },
      { kind: 'text', text: 'Лента EUROBAND НЛ – это готовый к применению продукт. При установке ленты EUROBAND НЛ не требуется специальных инструментов. Перед монтажом ленты необходимо очистить поверхность оконного проема от строительного мусора, пыли или наледи. При необходимости следует обработать поверхность стен (стыков и швов) грунтовочным составом. Раскраивать ленту рекомендуется на ровной поверхности. Лента должна быть приклеена плотно по всей своей длине. Это необходимо для того, чтобы исключить проникновение дождевой воды в монтажную пену и обеспечить качественную герметизацию стыков и швов. Стыковка герметизирующей водоизоляционной ленты производится внахлест. Рекомендуется приклеивать ленту до полного расширения монтажной пены. Это нужно для того, чтобы монтажная пена при расширении приклеила к себе ленту и немного ее натянула.' },
      { kind: 'text', text: 'Длина ленты, необходимая для монтажа в конкретном случае, складывается из габаритного размера оконного блока по горизонтали с добавлением отрезка ленты, равного ее ширине. Прибавление ширины ленты требуется для организации надежной водоизоляции в нижних углах оконного проема. Лента НЛ с обоих концов вдоль посередине надрезается на длину, равную половине своей ширины. Затем с ленты удаляется антиадгезионная прокладка, защищающая клейкую монтажную полосу, и она крепится к коробке оконного блока. Со второй монтажно-герметизирующей полосы ленты снимается антиадгезионная прокладка, и лента приклеивается к боковым наружным откосам, а затем к нижнему откосу. При этом надрезанные концы загибаются на боковые наружные откосы, захлестываясь на уже приклеенные загибы ленты. На следующем этапе при помощи саморезов с шагом в 50 см крепится отлив.' },
      { kind: 'text', text: 'Ленту EUROBAND НЛ рекомендуется устанавливать под наружным отливом, а также по всему периметру окна в тех случаях, когда установка ПСУЛа невозможна (отсутствуют четверти). После установки ленту необходимо закрыть нащельником для предотвращения попадания прямых солнечных лучей. Максимальный срок пребывания ленты на солнце - 2 месяца.' },
    ]
  },
